negativeControls.script:
async () => {
  // M12 negative controls: do Safari's getCompilationInfo and error scopes report at all?
  // Same layouts and descriptors as docs/plans/assets/2026-09-27-transparent-sort-validate-wgsl.js.
  const { primitiveGroup0LayoutEntries, textureTierLayoutEntries } = await import('/src/render/primitive-bindings.ts');
  const { SCENE_HDR_FORMAT } = await import('/src/render/formats.ts');
  const { ForwardPass } = await import('/src/render/passes/forward-pass.ts');
  const { TransparentSortPass } = await import('/src/render/passes/transparent-sort-pass.ts');

  const adapter = await navigator.gpu.requestAdapter({ powerPreference: 'low-power' });
  const device = await adapter.requestDevice();
  const g0 = device.createBindGroupLayout({ entries: primitiveGroup0LayoutEntries() });
  const g1 = device.createBindGroupLayout({ entries: textureTierLayoutEntries() });
  const g2 = device.createBindGroupLayout({
    entries: [
      { binding: 0, visibility: GPUShaderStage.FRAGMENT, texture: { sampleType: 'float', viewDimension: '2d-array' } },
      { binding: 1, visibility: GPUShaderStage.FRAGMENT, sampler: { type: 'filtering' } },
      { binding: 2, visibility: GPUShaderStage.FRAGMENT, buffer: { type: 'uniform' } },
    ],
  });
  const forwardLayout = device.createPipelineLayout({ bindGroupLayouts: [g0, g1, g2] });
  const blend = {
    color: { srcFactor: 'src-alpha', dstFactor: 'one-minus-src-alpha', operation: 'add' },
    alpha: { srcFactor: 'one', dstFactor: 'one-minus-src-alpha', operation: 'add' },
  };
  const transparent = (module) => ({
    layout: forwardLayout,
    vertex: { module, entryPoint: 'vs_main', buffers: [{ arrayStride: 12, attributes: [{ shaderLocation: 0, offset: 0, format: 'float32x3' }] }] },
    primitive: { topology: 'triangle-list', cullMode: 'back' },
    fragment: { module, entryPoint: 'fs_main', targets: [{ format: SCENE_HDR_FORMAT, blend }] },
    depthStencil: { format: 'depth24plus', depthWriteEnabled: false, depthCompare: 'less' },
  });
  const scoped = async (fn) => {
    device.pushErrorScope('internal');
    device.pushErrorScope('validation');
    let thrown = null;
    try { fn(); } catch (err) { thrown = err; }
    const validation = await device.popErrorScope();
    const internal = await device.popErrorScope();
    return [thrown && ('threw: ' + String(thrown)), validation && ('validation: ' + validation.message), internal && ('internal: ' + internal.message)].filter(Boolean).map((s) => s.slice(0, 600));
  };
  const compile = async (code) => {
    let module = null;
    const moduleErrors = await scoped(() => { module = device.createShaderModule({ code }); });
    const info = await module.getCompilationInfo();
    return { module, moduleErrors, messages: info.messages.map((m) => `${m.type} ${m.lineNum}:${m.linePos} ${m.message}`.slice(0, 600)) };
  };

  const out = {};
  const uber = ForwardPass.UBER_SOURCE;
  const firstLine = uber.split('\n')[0];
  out.uberFirstLine = firstLine;

  // C0: the uber as published (should be clean, as in the validator).
  {
    const c = await compile(uber);
    out.uberPublished = { moduleErrors: c.moduleErrors, messages: c.messages, pipeline: await scoped(() => device.createRenderPipeline(transparent(c.module))) };
  }
  // C1: the uber WITHOUT its diagnostic line (is the directive load-bearing on WebKit?).
  {
    const noDirective = uber.replace(/^diagnostic\(off, derivative_uniformity\);[^\n]*\n/, '');
    const c = await compile(noDirective);
    out.uberWithoutDirective = { removed: noDirective.length !== uber.length, moduleErrors: c.moduleErrors, messages: c.messages, pipeline: await scoped(() => device.createRenderPipeline(transparent(c.module))) };
  }
  // C2: a syntax error (must be reported by both channels).
  {
    const c = await compile('fn broken( {');
    out.syntaxError = { moduleErrors: c.moduleErrors, messages: c.messages, pipeline: await scoped(() => device.createRenderPipeline({
      layout: 'auto',
      vertex: { module: c.module, entryPoint: 'vs' },
      fragment: { module: c.module, entryPoint: 'fs', targets: [{ format: 'rgba8unorm' }] },
    })) };
  }
  // C3: minimal fwidth under a per-fragment branch, without and with the directive.
  const tiny = (directive) => `${directive}
@vertex fn vs(@builtin(vertex_index) i: u32) -> @builtin(position) vec4f { return vec4f(f32(i), 0.0, 0.0, 1.0); }
struct In { @location(0) v: vec2f, @location(1) @interpolate(flat) k: u32 }
@fragment fn fs(inp: In) -> @location(0) vec4f {
  var r = 0.0;
  if (inp.k == 1u) { r = fwidth(inp.v.x); }
  return vec4f(r);
}`;
  for (const [name, directive] of [['tinyNoDirective', ''], ['tinyWithDirective', 'diagnostic(off, derivative_uniformity);']]) {
    const c = await compile(tiny(directive));
    out[name] = { moduleErrors: c.moduleErrors, messages: c.messages };
  }
  // C4: a compute pipeline with a wrong entry point (must fail validation in the scope).
  {
    const c = await compile(TransparentSortPass.SORT_SOURCE);
    out.computeBadEntry = { messages: c.messages, pipeline: await scoped(() => device.createComputePipeline({ layout: 'auto', compute: { module: c.module, entryPoint: 'no_such_entry' } })) };
  }
  // C5: the uber on a TWO-group layout (the occluder layout): its fs_main reaches group 2
  // (lit quad/gradient cases), so the pipeline must fail validation.
  {
    const c = await compile(uber);
    const d = transparent(c.module);
    d.layout = device.createPipelineLayout({ bindGroupLayouts: [g0, g1] });
    out.uberTwoGroupLayout = { pipeline: await scoped(() => device.createRenderPipeline(d)) };
  }
  const { vendor, architecture, description } = adapter.info ?? {};
  device.destroy();
  return { adapter: { vendor, architecture, description }, ...out };
}
